What happens when the following loop runs?

for (int i = 5; i >= 0; i--) {
    printf("%d ", i);
}
printf("Liftoff!");

What happens when we try to remove even numbers from a vector using this code?

vector<int> nums = {1, 2, 3, 4, 5, 6};
for (auto it = nums.begin(); it != nums.end(); ++it) {
    if (*it % 2 == 0) {
        nums.erase(it);
    }
}

